// @FIGURE_CODE_BEGIN
// ── element spec ────────────────────────────────────────────────────────────
// ground plane      → BoxGeometry(8.5, 0.06, 6)  offset so hit pt is left/front  MeshBasic #7CFC00
// plane outline     → 4 × BoxGeometry thin bars           MeshBasic #000000
// hit-point ellipse → TorusGeometry(0.25, 0.03) in XZ     MeshBasic #000000
// incoming beam     → tapered CylinderGeometry, vertexColors yellow→orange→red
// beam arrowhead    → ConeGeometry(0.22, 0.55)            MeshBasic #FF1A00
// normal n          → Arrow(cyl 0.07 + cone 0.18×0.42)    MeshBasic #000000
// right-angle mark  → 2 × thin BoxGeometry in XY plane    MeshBasic #000000
// tangents p, q     → Arrow(cyl 0.055 + cone 0.16×0.36)   MeshBasic #000000
// main outgoing     → Arrow(cyl 0.10 + cone 0.30×0.66)    MeshBasic #14620C  (thick, dark, longest)
// scattered lobe    → 56 × Arrow(cyl 0.05 + cone 0.14×0.32) #5FD13A, 50% alpha
// labels            → addLabel HTML (italic serif / bold)
// ────────────────────────────────────────────────────────────────────────────

const ORIGIN = new THREE.Vector3(0, 0, 0);
const UP = new THREE.Vector3(0, 1, 0);

/* ── reusable arrow ─────────────────────────────────────────────────────── */
function makeArrow({ color = 0x000000, shaft = 0.06, headR = 0.16, headL = 0.36,
                     opacity = 1, transparent = false, renderOrder = 0 } = {}) {
  const mat = new THREE.MeshBasicMaterial({
    color, transparent, opacity, depthWrite: !transparent
  });
  const sg = new THREE.CylinderGeometry(shaft, shaft, 1, 12); sg.translate(0, 0.5, 0);
  const hg = new THREE.ConeGeometry(headR, headL, 18);        hg.translate(0, headL / 2, 0);
  const sm = new THREE.Mesh(sg, mat), hm = new THREE.Mesh(hg, mat);
  sm.renderOrder = hm.renderOrder = renderOrder;
  const g = new THREE.Group(); g.add(sm); g.add(hm);
  g.userData.set = (dir, L) => {
    const len = Math.max(L, headL * 1.02);
    sm.scale.y = Math.max(1e-3, len - headL);
    hm.position.y = len - headL;
    g.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
  };
  g.userData.mat = mat;
  return g;
}

/* ── ground plane (smaller, so the lobe reads large as in the source) ───── */
const PW = 8.5, PD = 6.0;
const planeGroup = new THREE.Group();
const slab = new THREE.Mesh(
  new THREE.BoxGeometry(PW, 0.06, PD),
  new THREE.MeshBasicMaterial({ color: 0x7CFC00 })
);
slab.position.y = -0.03;
planeGroup.add(slab);

const blackMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
const EB = 0.10;
[[PW + EB, EB, EB, 0, 0,  PD / 2], [PW + EB, EB, EB, 0, 0, -PD / 2],
 [EB, EB, PD + EB,  PW / 2, 0, 0], [EB, EB, PD + EB, -PW / 2, 0, 0]].forEach(e => {
  const b = new THREE.Mesh(new THREE.BoxGeometry(e[0], e[1], e[2]), blackMat);
  b.position.set(e[3], e[4], e[5]);
  planeGroup.add(b);
});
// hit point sits left of the plane's centre and in its front half, as in the source
planeGroup.position.set(1.1, 0, -1.1);
scene.add(planeGroup);

/* ── hit-point mark ─────────────────────────────────────────────────────── */
const hitRing = new THREE.Mesh(new THREE.TorusGeometry(0.25, 0.03, 8, 40), blackMat);
hitRing.rotation.x = -Math.PI / 2;
hitRing.position.y = 0.014;
scene.add(hitRing);

/* ── incoming beam ──────────────────────────────────────────────────────── */
const BEAM_LEN = 5.6, BEAM_HEAD = 0.55;
const beamGroup = new THREE.Group();
const bodyLen = BEAM_LEN - BEAM_HEAD;
const beamGeo = new THREE.CylinderGeometry(0.16, 0.10, bodyLen, 18, 26);
beamGeo.translate(0, BEAM_HEAD + bodyLen / 2, 0);
{
  const pos = beamGeo.attributes.position;
  const cols = new Float32Array(pos.count * 3);
  const cRed = new THREE.Color(0xFF1A00), cOra = new THREE.Color(0xFF9000), cYel = new THREE.Color(0xFFE800);
  const tmp = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const t = Math.min(1, Math.max(0, (pos.getY(i) - BEAM_HEAD) / bodyLen));
    if (t < 0.5) tmp.copy(cRed).lerp(cOra, t * 2);
    else         tmp.copy(cOra).lerp(cYel, (t - 0.5) * 2);
    cols[i * 3] = tmp.r; cols[i * 3 + 1] = tmp.g; cols[i * 3 + 2] = tmp.b;
  }
  beamGeo.setAttribute('color', new THREE.BufferAttribute(cols, 3));
}
const beamBody = new THREE.Mesh(beamGeo, new THREE.MeshBasicMaterial({ vertexColors: true }));
const beamHeadGeo = new THREE.ConeGeometry(0.22, BEAM_HEAD, 20);
beamHeadGeo.rotateX(Math.PI);                 // apex points toward -Y
beamHeadGeo.translate(0, BEAM_HEAD / 2, 0);   // apex sits at the hit point
const beamHead = new THREE.Mesh(beamHeadGeo, new THREE.MeshBasicMaterial({ color: 0xFF1A00 }));
beamGroup.add(beamBody); beamGroup.add(beamHead);
scene.add(beamGroup);

/* ── normal, right-angle marker, tangents ───────────────────────────────── */
const nArrow = makeArrow({ color: 0x000000, shaft: 0.07, headR: 0.18, headL: 0.42, renderOrder: 4 });
nArrow.userData.set(UP, 1.7);
scene.add(nArrow);

const raGroup = new THREE.Group();
const raBarA = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.32, 0.05), blackMat);
raBarA.position.set(0.32, 0.16, 0);
const raBarB = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.05, 0.05), blackMat);
raBarB.position.set(0.16, 0.32, 0);
raGroup.add(raBarA); raGroup.add(raBarB);
raGroup.renderOrder = 4;
scene.add(raGroup);

const pDir = new THREE.Vector3(-1.15, 0, -0.45).normalize();
const qDir = new THREE.Vector3(1.15, 0, -0.45).normalize();
const pArrow = makeArrow({ color: 0x000000, shaft: 0.055, headR: 0.16, headL: 0.36, renderOrder: 4 });
const qArrow = makeArrow({ color: 0x000000, shaft: 0.055, headR: 0.16, headL: 0.36, renderOrder: 4 });
pArrow.userData.set(pDir, 1.35); qArrow.userData.set(qDir, 1.35);
pArrow.position.y = 0.04; qArrow.position.y = 0.04;
scene.add(pArrow); scene.add(qArrow);

/* ── outgoing lobe ──────────────────────────────────────────────────────── */
const mainArrow = makeArrow({ color: 0x14620C, shaft: 0.10, headR: 0.30, headL: 0.66, renderOrder: 5 });
scene.add(mainArrow);

const N_LOBE = 56;
const LOBE_SCALE = 1.6, LOBE_MAX = 3.6, LOBE_MIN_VIS = 0.35;
const lobeDirs = [], lobeArrows = [];
const GOLD = Math.PI * (3 - Math.sqrt(5));
for (let i = 0; i < N_LOBE; i++) {
  const y = 0.05 + 0.93 * ((i + 0.5) / N_LOBE);
  const rr = Math.sqrt(Math.max(0, 1 - y * y));
  const phi = i * GOLD;
  lobeDirs.push(new THREE.Vector3(rr * Math.cos(phi), y, rr * Math.sin(phi)).normalize());
  const a = makeArrow({
    color: 0x5FD13A, shaft: 0.05, headR: 0.14, headL: 0.32,
    transparent: true, opacity: 0.5, renderOrder: 2
  });
  a.position.y = 0.03;
  scene.add(a);
  lobeArrows.push(a);
}

/* ── state ──────────────────────────────────────────────────────────────── */
const MATERIALS = {
  'Lambertian': { kd: 1.00, ks: 0.00, mCap: 4000 },
  'Glossy (diffuse + specular)': { kd: 0.35, ks: 0.65, mCap: 4000 },
  'Mirror': { kd: 0.02, ks: 0.98, mCap: 4000 }
};
const state = {
  material: 'Glossy (diffuse + specular)',
  roughness: 0.35,
  thetaDeg: 44.4,                       // angle of incidence from the normal
  azDeg: THREE.MathUtils.radToDeg(Math.atan2(0.34, -0.612))
};

function incomingDir() {
  const th = THREE.MathUtils.degToRad(THREE.MathUtils.clamp(state.thetaDeg, 0, 87));
  const az = THREE.MathUtils.degToRad(state.azDeg);
  const s = Math.sin(th);
  return new THREE.Vector3(s * Math.cos(az), Math.cos(th), s * Math.sin(az)).normalize();
}

/* ── labels ─────────────────────────────────────────────────────────────── */
const SER = "font-family:'Times New Roman',Georgia,serif;font-style:italic;";
const lblIn = addLabel(
  `<span style="${SER}">&#8467;<sub>in</sub>(<span style="font-style:normal">&lambda;</span>)</span>`,
  new THREE.Vector3(0, 0, 0), { fontSize: '25px', offset: [76, 6] });
const lblOut = addLabel(
  `<span style="${SER}">&#8467;<sub>out</sub>=F(&#8467;<sub>in</sub>,<b style="font-style:normal">n</b>,` +
  `<span style="font-style:normal">&lambda;</span>,<b style="font-style:normal">p</b>,` +
  `<b style="font-style:normal">q</b>)</span>`,
  new THREE.Vector3(0, 0, 0), { fontSize: '22px', offset: [122, -20] });
addLabel('<b>n</b>', new THREE.Vector3(0, 1.82, 0), { fontSize: '22px', bold: true, offset: [-16, -14] });
addLabel('<b>p</b>', pDir.clone().multiplyScalar(1.55).setY(0.18), { fontSize: '22px', bold: true, offset: [-16, -10] });
addLabel('<b>q</b>', qDir.clone().multiplyScalar(1.55).setY(0.18), { fontSize: '22px', bold: true, offset: [18, -10] });

/* ── BRDF evaluation & scene update ─────────────────────────────────────── */
function updateScene() {
  const wi = incomingDir();
  const cosI = Math.max(0, wi.y);
  const rDir = new THREE.Vector3(-wi.x, wi.y, -wi.z).normalize();   // 2(n·wi)n − wi
  const M = MATERIALS[state.material];
  const m = Math.min(M.mCap, Math.max(0, 2 / (state.roughness * state.roughness) - 2));
  const floor = 0.15 + 0.85 * M.kd;        // diffuse visibility floor

  // incoming beam
  beamGroup.quaternion.setFromUnitVectors(UP, wi);

  // main outgoing arrow (mirror direction) — always the longest, thickest, darkest
  const mainLen = 1.8 + 3.2 * cosI;
  mainArrow.userData.set(rDir, mainLen);

  // scattered hemisphere
  for (let i = 0; i < N_LOBE; i++) {
    const d = lobeDirs[i];
    const spec = Math.max(0, rDir.dot(d));
    const fr = M.kd / Math.PI + M.ks * (m + 2) / (2 * Math.PI) * Math.pow(spec, m);
    let L = (floor + 3.0 * fr * cosI) * LOBE_SCALE;
    L = Math.min(LOBE_MAX, Math.max(0, L));
    const a = lobeArrows[i];
    if (L < LOBE_MIN_VIS) { a.visible = false; }
    else { a.visible = true; a.userData.set(d, L); }
  }

  // labels that follow the geometry
  lblIn.pos.copy(wi).multiplyScalar(0.8 * BEAM_LEN);
  lblOut.pos.copy(rDir).multiplyScalar(mainLen + 0.3);
}
updateScene();

/* ── camera (after all geometry) — shallow elevation → wide flat plane ──── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 16, z: 24 },
  rollDeg: 0,
  heightFraction: 0.64
});

/* ── explainers ─────────────────────────────────────────────────────────── */
registerInteractive(nArrow, {
  title: 'Surface normal n',
  tooltip: 'Surface normal n',
  body: 'n is the unit vector perpendicular to the surface at the hit point. Together with the in-plane vectors p and q it defines the local frame in which the BRDF F is expressed, and the mirror direction is r = 2(n·ℓ_in)n − ℓ_in.'
});
registerInteractive(mainArrow, {
  title: 'Outgoing radiance ℓ_out',
  tooltip: 'ℓ_out = F(ℓ_in, n, λ, p, q)',
  body: 'The radiance leaving toward one particular viewing direction. Its length is F (the BRDF) times the incident irradiance ℓ_in·cos θ_i. Every light-green arrow is the same quantity evaluated for a different outgoing direction — together they trace the reflectance lobe.'
});
registerInteractive(planeGroup, {
