    transparent: true, opacity: 0.5, renderOrder: 2
  });
  a.position.y = 0.03;
  scene.add(a);
  lobeArrows.push(a);
}

/* ── state ──────────────────────────────────────────────────────────────── */
const MATERIALS = {
  'Lambertian': { kd: 1.00, ks: 0.00, mCap: 4000 },
  'Glossy (diffuse + specular)': { kd: 0.35, ks: 0.65, mCap: 4000 },
  'Mirror': { kd: 0.02, ks: 0.98, mCap: 4000 }
};
const state = {
  material: 'Glossy (diffuse + specular)',
  roughness: 0.35,
  thetaDeg: 44.4,                       // angle of incidence from the normal
  azDeg: THREE.MathUtils.radToDeg(Math.atan2(0.34, -0.612))
};

function incomingDir() {
  const th = THREE.MathUtils.degToRad(THREE.MathUtils.clamp(state.thetaDeg, 0, 87));
  const az = THREE.MathUtils.degToRad(state.azDeg);
  const s = Math.sin(th);
  return new THREE.Vector3(s * Math.cos(az), Math.cos(th), s * Math.sin(az)).normalize();
}

/* ── labels ─────────────────────────────────────────────────────────────── */
const SER = "font-family:'Times New Roman',Georgia,serif;font-style:italic;";
const lblIn = addLabel(
  `<span style="${SER}">&#8467;<sub>in</sub>(<span style="font-style:normal">&lambda;</span>)</span>`,
  new THREE.Vector3(0, 0, 0), { fontSize: '25px', offset: [76, 6] });
const lblOut = addLabel(
  `<span style="${SER}">&#8467;<sub>out</sub>=F(&#8467;<sub>in</sub>,<b style="font-style:normal">n</b>,` +
  `<span style="font-style:normal">&lambda;</span>,<b style="font-style:normal">p</b>,` +
  `<b style="font-style:normal">q</b>)</span>`,
  new THREE.Vector3(0, 0, 0), { fontSize: '22px', offset: [122, -20] });
addLabel('<b>n</b>', new THREE.Vector3(0, 1.82, 0), { fontSize: '22px', bold: true, offset: [-16, -14] });
addLabel('<b>p</b>', pDir.clone().multiplyScalar(1.55).setY(0.18), { fontSize: '22px', bold: true, offset: [-16, -10] });
addLabel('<b>q</b>', qDir.clone().multiplyScalar(1.55).setY(0.18), { fontSize: '22px', bold: true, offset: [18, -10] });

/* ── BRDF evaluation & scene update ─────────────────────────────────────── */
function updateScene() {
  const wi = incomingDir();
  const cosI = Math.max(0, wi.y);
  const rDir = new THREE.Vector3(-wi.x, wi.y, -wi.z).normalize();   // 2(n·wi)n − wi
  const M = MATERIALS[state.material];
  const m = Math.min(M.mCap, Math.max(0, 2 / (state.roughness * state.roughness) - 2));
  const floor = 0.15 + 0.85 * M.kd;        // diffuse visibility floor

  // incoming beam
  beamGroup.quaternion.setFromUnitVectors(UP, wi);

  // main outgoing arrow (mirror direction) — always the longest, thickest, darkest
  const mainLen = 1.8 + 3.2 * cosI;
  mainArrow.userData.set(rDir, mainLen);

  // scattered hemisphere
  for (let i = 0; i < N_LOBE; i++) {
    const d = lobeDirs[i];
    const spec = Math.max(0, rDir.dot(d));
    const fr = M.kd / Math.PI + M.ks * (m + 2) / (2 * Math.PI) * Math.pow(spec, m);
    let L = (floor + 3.0 * fr * cosI) * LOBE_SCALE;
    L = Math.min(LOBE_MAX, Math.max(0, L));
    const a = lobeArrows[i];
    if (L < LOBE_MIN_VIS) { a.visible = false; }
    else { a.visible = true; a.userData.set(d, L); }
  }

  // labels that follow the geometry
  lblIn.pos.copy(wi).multiplyScalar(0.8 * BEAM_LEN);
  lblOut.pos.copy(rDir).multiplyScalar(mainLen + 0.3);
}
updateScene();

/* ── camera (after all geometry) — shallow elevation → wide flat plane ──── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 16, z: 24 },
  rollDeg: 0,
  heightFraction: 0.64
});

/* ── explainers ─────────────────────────────────────────────────────────── */
registerInteractive(nArrow, {
  title: 'Surface normal n',
  tooltip: 'Surface normal n',
  body: 'n is the unit vector perpendicular to the surface at the hit point. Together with the in-plane vectors p and q it defines the local frame in which the BRDF F is expressed, and the mirror direction is r = 2(n·ℓ_in)n − ℓ_in.'
});
registerInteractive(mainArrow, {
  title: 'Outgoing radiance ℓ_out',
  tooltip: 'ℓ_out = F(ℓ_in, n, λ, p, q)',
  body: 'The radiance leaving toward one particular viewing direction. Its length is F (the BRDF) times the incident irradiance ℓ_in·cos θ_i. Every light-green arrow is the same quantity evaluated for a different outgoing direction — together they trace the reflectance lobe.'
});
registerInteractive(planeGroup, {
  title: 'The surface patch',
  tooltip: 'Surface patch (local frame p, q)',
  body: 'A flat differential patch of the material. The BRDF is defined per point on this patch: it maps every incoming direction to a distribution of outgoing radiance over the upper hemisphere, expressed in the tangent frame (p, q, n).'
});

/* ── drag the incoming beam ─────────────────────────────────────────────── */
const _dragRay = new THREE.Raycaster();
const _ptr = new THREE.Vector2();
const _grabSphere = new THREE.Sphere(ORIGIN, 4);
let draggingBeam = false;

function pointerToRay(ev) {
  const rect = canvas.getBoundingClientRect();
  _ptr.x = ((ev.clientX - rect.left) / rect.width) * 2 - 1;
  _ptr.y = -((ev.clientY - rect.top) / rect.height) * 2 + 1;
  _dragRay.setFromCamera(_ptr, camera);
}

canvas.addEventListener('pointerdown', (ev) => {
  pointerToRay(ev);
  const hits = _dragRay.intersectObjects([beamBody, beamHead], false);
  if (hits.length) {
    draggingBeam = true;
    controls.enabled = false;
    canvas.style.cursor = 'grabbing';
    ev.stopPropagation();
  }
}, true);

window.addEventListener('pointerup', () => {
  if (draggingBeam) {
    draggingBeam = false;
    controls.enabled = true;
    canvas.style.cursor = 'default';
  }
});

canvas.addEventListener('pointermove', (ev) => {
  if (!draggingBeam) return;
  pointerToRay(ev);
  const hit = new THREE.Vector3();
  let ok = _dragRay.ray.intersectSphere(_grabSphere, hit);
  if (!ok) { _dragRay.ray.closestPointToPoint(ORIGIN, hit); }
  if (hit.lengthSq() < 1e-6) return;
  hit.normalize();
  if (hit.y < 0.08) { hit.y = 0.08; hit.normalize(); }
  state.thetaDeg = THREE.MathUtils.clamp(THREE.MathUtils.radToDeg(Math.acos(hit.y)), 0, 85);
  state.azDeg = THREE.MathUtils.radToDeg(Math.atan2(hit.z, hit.x));
  incEl.value = state.thetaDeg.toFixed(0);
  incValEl.textContent = state.thetaDeg.toFixed(0) + '\u00B0';
  updateScene();
}, true);

/* ── UI wiring ──────────────────────────────────────────────────────────── */
const roughEl = document.getElementById('rough');
const roughValEl = document.getElementById('roughVal');
const incEl = document.getElementById('inc');
const incValEl = document.getElementById('incVal');
const matBtns = {
  'Lambertian': document.getElementById('btnLam'),
  'Glossy (diffuse + specular)': document.getElementById('btnGlo'),
  'Mirror': document.getElementById('btnMir')
};

function setMaterial(name) {
  state.material = name;
  for (const k in matBtns) matBtns[k].classList.toggle('active', k === name);
  updateScene();
}
for (const k in matBtns) matBtns[k].addEventListener('click', () => setMaterial(k));

roughEl.addEventListener('input', () => {
  state.roughness = parseFloat(roughEl.value);
  roughValEl.textContent = state.roughness.toFixed(2);
  updateScene();
});
incEl.addEventListener('input', () => {
  state.thetaDeg = parseFloat(incEl.value);
  incValEl.textContent = state.thetaDeg.toFixed(0) + '\u00B0';
  updateScene();
});
incEl.value = state.thetaDeg.toFixed(0);
incValEl.textContent = state.thetaDeg.toFixed(0) + '\u00B0';

/* ── guided demo (tweened) ──────────────────────────────────────────────── */
const STEPS = [
  { title: '1. Glossy surface, oblique light',
    text: 'A single incoming ray ℓ_in(λ) strikes the point. Outgoing arrows fill the whole hemisphere, but the longest cluster leans toward the mirror direction — this is ℓ_out = F(ℓ_in, n, λ, p, q).',
    material: 'Glossy (diffuse + specular)', roughness: 0.35, theta: 44 },
  { title: '2. Perfectly diffuse',
    text: 'With a Lambertian F every outgoing arrow has the same length: the surface looks equally bright from all viewpoints, and only cos θ_i sets the overall brightness.',
    material: 'Lambertian', roughness: 1.0, theta: 44 },
  { title: '3. Mirror limit',
    text: 'Shrink roughness toward zero and the hemisphere collapses to one arrow in the mirror direction — specular reflection is the degenerate case of the BRDF.',
    material: 'Mirror', roughness: 0.02, theta: 44 },
  { title: '4. Grazing incidence',
    text: 'Swing ℓ_in toward the horizon: the lobe follows the mirror direction and every arrow shortens, because the same beam spreads its power over a larger patch (cos θ_i falloff).',
    material: 'Glossy (diffuse + specular)', roughness: 0.35, theta: 80 }
];
let stepIdx = 0;
let tween = null;

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepText').textContent = s.text;
  setMaterial(s.material);
  tween = {
    t0: performance.now(), dur: 700,
    r0: state.roughness, r1: s.roughness,
    a0: state.thetaDeg, a1: s.theta
  };
}
function tickTween() {
  requestAnimationFrame(tickTween);
  if (!tween) return;
  const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
  const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
  state.roughness = tween.r0 + (tween.r1 - tween.r0) * e;
  state.thetaDeg = tween.a0 + (tween.a1 - tween.a0) * e;
  roughEl.value = state.roughness.toFixed(2);
  roughValEl.textContent = state.roughness.toFixed(2);
  incEl.value = state.thetaDeg.toFixed(0);
  incValEl.textContent = state.thetaDeg.toFixed(0) + '\u00B0';
  updateScene();
  if (k >= 1) tween = null;
}
tickTween();

document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('stepTitle').textContent = STEPS[0].title;
document.getElementById('stepText').textContent = STEPS[0].text;

document.getElementById('btnReset').style.display = '';
// @FIGURE_CODE_END

