<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:700;font-size:12px;margin-bottom:-2px">BRDF&nbsp;&nbsp;<i>F</i>(&#8467;<sub>in</sub>, n, &lambda;, p, q)</div>
