// @FIGURE_CODE_BEGIN
// ── element spec ────────────────────────────────────────────────────────────
// ground plane      → BoxGeometry(7.0, 0.06, 5.0) offset so hit pt is left/front  MeshBasic #7CFC00
// plane outline     → 4 × BoxGeometry thin bars (0.09)            MeshBasic #000000
// hit-point ellipse → TorusGeometry(0.34, 0.045) in XZ            MeshBasic #000000
// incoming beam     → tapered CylinderGeometry(0.22→0.14), vertexColors yellow→orange→red
// beam arrowhead    → ConeGeometry(0.32, 0.80)                    MeshBasic #FF1A00
// normal n          → Arrow(cyl 0.085 + cone 0.24×0.52) depthTest:false  #000000, L=2.05
// right-angle mark  → 2 × BoxGeometry bars, side 0.45, billboarded about Y  #000000
// tangents p, q     → Arrow(cyl 0.085 + cone 0.24×0.50) depthTest:false #000000, L=1.95, tilted up
// main outgoing     → Arrow(cyl 0.125 + cone 0.36×0.82)           MeshBasic #1E7B14
// scattered lobe    → 48 × Arrow(cyl 0.065 + cone 0.19×0.42) #4CC22E, 55% alpha
// labels            → addLabel HTML (italic serif / bold)
// ────────────────────────────────────────────────────────────────────────────

const ORIGIN = new THREE.Vector3(0, 0, 0);
const UP = new THREE.Vector3(0, 1, 0);

/* ── reusable arrow ─────────────────────────────────────────────────────── */
function makeArrow({ color = 0x000000, shaft = 0.06, headR = 0.16, headL = 0.36,
                     opacity = 1, transparent = false, renderOrder = 0,
                     depthTest = true } = {}) {
  const mat = new THREE.MeshBasicMaterial({
    color, transparent, opacity, depthWrite: !transparent && depthTest, depthTest
  });
  const sg = new THREE.CylinderGeometry(shaft, shaft, 1, 14); sg.translate(0, 0.5, 0);
  const hg = new THREE.ConeGeometry(headR, headL, 20);        hg.translate(0, headL / 2, 0);
  const sm = new THREE.Mesh(sg, mat), hm = new THREE.Mesh(hg, mat);
  sm.renderOrder = hm.renderOrder = renderOrder;
  const g = new THREE.Group(); g.add(sm); g.add(hm);
  g.renderOrder = renderOrder;
  g.userData.set = (dir, L) => {
    const len = Math.max(L, headL * 1.02);
    sm.scale.y = Math.max(1e-3, len - headL);
    hm.position.y = len - headL;
    g.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
  };
  g.userData.mat = mat;
  return g;
}

