    const t = Math.min(1, Math.max(0, (pos.getY(i) - BEAM_HEAD) / bodyLen));
    if (t < 0.5) tmp.copy(cRed).lerp(cOra, t * 2);
    else         tmp.copy(cOra).lerp(cYel, (t - 0.5) * 2);
    cols[i * 3] = tmp.r; cols[i * 3 + 1] = tmp.g; cols[i * 3 + 2] = tmp.b;
  }
  beamGeo.setAttribute('color', new THREE.BufferAttribute(cols, 3));
}
const beamBody = new THREE.Mesh(beamGeo, new THREE.MeshBasicMaterial({ vertexColors: true }));
const beamHeadGeo = new THREE.ConeGeometry(0.32, BEAM_HEAD, 22);
beamHeadGeo.rotateX(Math.PI);                 // apex points toward -Y
