/* ── BRDF evaluation & scene update ─────────────────────────────────────── */
function updateScene() {
  const wi = incomingDir();
  const cosI = Math.max(0, wi.y);
  const rDir = new THREE.Vector3(-wi.x, wi.y, -wi.z).normalize();   // 2(n·wi)n − wi
  const M = MATERIALS[state.material];
  const m = Math.min(M.mCap, Math.max(0, 2 / (state.roughness * state.roughness) - 2));
  const floor = 0.15 + 0.85 * M.kd;        // diffuse visibility floor

  // incoming beam
  beamGroup.quaternion.setFromUnitVectors(UP, wi);

  // main outgoing arrow (mirror direction) — always the longest, thickest, darkest
  const mainLen = 1.9 + 2.8 * cosI;
  mainArrow.userData.set(rDir, mainLen);

  // scattered hemisphere
  for (let i = 0; i < N_LOBE; i++) {
    const dd = lobeDirs[i];
    const spec = Math.max(0, rDir.dot(dd));
    const fr = M.kd / Math.PI + M.ks * (m + 2) / (2 * Math.PI) * Math.pow(spec, m);
    let L = (floor + 3.0 * fr * cosI) * LOBE_SCALE;
    L = Math.min(LOBE_MAX, Math.max(0, L));
    const a = lobeArrows[i];
    if (L < LOBE_MIN_VIS) { a.visible = false; }
    else { a.visible = true; a.userData.set(dd, L); }
  }

  // labels that follow the geometry
  lblIn.pos.copy(wi).multiplyScalar(0.66 * BEAM_LEN);
  lblOut.pos.copy(rDir).multiplyScalar(mainLen + 0.3);
}
updateScene();

