/* ── keep the right-angle bracket square-on to the camera ───────────────── */
const _camRight = new THREE.Vector3(), _hDir = new THREE.Vector3(), _zAxis = new THREE.Vector3();
const _basis = new THREE.Matrix4();
function updateRightAngle() {
  camera.updateMatrixWorld();
  _camRight.setFromMatrixColumn(camera.matrixWorld, 0);
  _hDir.set(_camRight.x, 0, _camRight.z);
  if (_hDir.lengthSq() < 1e-6) _hDir.set(1, 0, 0);
  _hDir.normalize();
  // put the bracket on the side AWAY from the incoming beam, as in the source
  const wi = incomingDir();
  if (_hDir.x * wi.x + _hDir.z * wi.z > 0) _hDir.multiplyScalar(-1);
  _zAxis.crossVectors(_hDir, UP).normalize();
  _basis.makeBasis(_hDir, UP, _zAxis);
  raGroup.quaternion.setFromRotationMatrix(_basis);
}
updateRightAngle();

