/* ── drag the incoming beam ─────────────────────────────────────────────── */
const _dragRay = new THREE.Raycaster();
const _ptr = new THREE.Vector2();
const _grabSphere = new THREE.Sphere(ORIGIN, 4);
let draggingBeam = false;

function pointerToRay(ev) {
  const rect = canvas.getBoundingClientRect();
  _ptr.x = ((ev.clientX - rect.left) / rect.width) * 2 - 1;
  _ptr.y = -((ev.clientY - rect.top) / rect.height) * 2 + 1;
  _dragRay.setFromCamera(_ptr, camera);
}

canvas.addEventListener('pointerdown', (ev) => {
  pointerToRay(ev);
  const hits = _dragRay.intersectObjects([beamBody, beamHead], false);
  if (hits.length) {
    draggingBeam = true;
    controls.enabled = false;
    canvas.style.cursor = 'grabbing';
    ev.stopPropagation();
  }
}, true);

window.addEventListener('pointerup', () => {
  if (draggingBeam) {
    draggingBeam = false;
    controls.enabled = true;
    canvas.style.cursor = 'default';
  }
});

canvas.addEventListener('pointermove', (ev) => {
  if (!draggingBeam) return;
  pointerToRay(ev);
  const hit = new THREE.Vector3();
  const ok = _dragRay.ray.intersectSphere(_grabSphere, hit);
  if (!ok) { _dragRay.ray.closestPointToPoint(ORIGIN, hit); }
  if (hit.lengthSq() < 1e-6) return;
  hit.normalize();
  if (hit.y < 0.08) { hit.y = 0.08; hit.normalize(); }
  state.thetaDeg = THREE.MathUtils.clamp(THREE.MathUtils.radToDeg(Math.acos(hit.y)), 0, 85);
  state.azDeg = THREE.MathUtils.radToDeg(Math.atan2(hit.z, hit.x));
  incEl.value = state.thetaDeg.toFixed(0);
  incValEl.textContent = state.thetaDeg.toFixed(0) + '\u00B0';
  updateScene();
}, true);

/* ── guided demo (tweened) ──────────────────────────────────────────────── */
const STEPS = [
  { title: '1. Glossy surface, oblique light',
    text: 'A single incoming ray ℓ_in(λ) strikes the point. Outgoing arrows fill the whole hemisphere, but the longest cluster leans toward the mirror direction — this is ℓ_out = F(ℓ_in, n, λ, p, q).',
    material: 'Glossy (diffuse + specular)', roughness: 0.35, theta: 46 },
  { title: '2. Perfectly diffuse',
    text: 'With a Lambertian F every outgoing arrow has the same length: the surface looks equally bright from all viewpoints, and only cos θ_i sets the overall brightness.',
    material: 'Lambertian', roughness: 1.0, theta: 46 },
  { title: '3. Mirror limit',
    text: 'Shrink roughness toward zero and the hemisphere collapses to one arrow in the mirror direction — specular reflection is the degenerate case of the BRDF.',
    material: 'Mirror', roughness: 0.02, theta: 46 },
  { title: '4. Grazing incidence',
    text: 'Swing ℓ_in toward the horizon: the lobe follows the mirror direction and every arrow shortens, because the same beam spreads its power over a larger patch (cos θ_i falloff).',
    material: 'Glossy (diffuse + specular)', roughness: 0.35, theta: 80 }
];
let stepIdx = 0;
let tween = null;

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepText').textContent = s.text;
  setMaterial(s.material);
  tween = {
    t0: performance.now(), dur: 700,
    r0: state.roughness, r1: s.roughness,
    a0: state.thetaDeg, a1: s.theta
  };
}
function tickTween() {
  requestAnimationFrame(tickTween);
  updateRightAngle();
  if (!tween) return;
  const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
  const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
  state.roughness = tween.r0 + (tween.r1 - tween.r0) * e;
  state.thetaDeg = tween.a0 + (tween.a1 - tween.a0) * e;
  roughEl.value = state.roughness.toFixed(2);
  roughValEl.textContent = state.roughness.toFixed(2);
  incEl.value = state.thetaDeg.toFixed(0);
  incValEl.textContent = state.thetaDeg.toFixed(0) + '\u00B0';
  updateScene();
  if (k >= 1) tween = null;
}
tickTween();

document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('stepTitle').textContent = STEPS[0].title;
document.getElementById('stepText').textContent = STEPS[0].text;

document.getElementById('btnReset').style.display = '';
